        let name = self.workspace.workspace_name().to_owned();
        let mut tx = self.start_tx();
        tx.repo_mut().check_out(name, &target).block_on()?;
        self.finish_tx(tx, &format!("new empty commit on {}", target.id().hex()))
    }

