    jj_ok(
        &fx.work,
        &["bookmark", "set", "main", "-r", "@-", "--allow-backwards"],
    );
    refused(&a, "sync first");

    jj_ok(&fx.work, &["new", "main@origin"]);
    fs::write(fx.work.join("other.txt"), "other\n").expect("write");
    jj_ok(&fx.work, &["commit", "-m", "feat: another cycle landed"]);
    jj_ok(
