    pub fn snapshot(&mut self) -> Result<()> {
        let files = self.snapshot_with(None)?;
        if files.is_empty() {
            return Ok(());
        }
        let repo = self.workspace.workspace_root().to_path_buf();
        Err(Box::new(FilesTooLarge {
            agent_repo: crate::common::is_bot_dir(&repo),
